export function resolveOfficeTheme(themeId: OfficeThemeId, domTheme: "dark" | "light"): OfficeAtmosphereTheme {
  if (themeId === "auto") {
    return domTheme === "light" ? OFFICE_THEMES.daylight : OFFICE_THEMES["tokyo-night"];
  }
  return OFFICE_THEMES[themeId];
}

