const DECODED_FRAME_CACHE = new Map<string, HTMLCanvasElement>();

function decodeRleIndices(b64: string, total: number): Uint8Array {
  let raw: Uint8Array;
  if (typeof Buffer !== "undefined") {
    const buf = Buffer.from(b64, "base64");
    raw = new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
  } else {
    const bin = atob(b64);
    raw = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) raw[i] = bin.charCodeAt(i);
  }
  const out = new Uint8Array(total);
  let pos = 0;
  for (let i = 0; i + 1 < raw.length && pos < total; i += 2) {
    const count = raw[i];
    const idx = raw[i + 1];
    const end = Math.min(total, pos + count);
    out.fill(idx, pos, end);
    pos = end;
  }
  return out;
}

export function decodePixtuoidFrameToIndices(key: PixtuoidSpriteKey, frameIndex = 0): {
  w: number;
  h: number;
  indices: Uint8Array;
} {
  const spec = PIXTUOID_SPRITES[key];
  const safeFrame = spec.frames[((frameIndex % spec.frames.length) + spec.frames.length) % spec.frames.length];
  return {
    w: spec.w,
    h: spec.h,
    indices: decodeRleIndices(safeFrame, spec.w * spec.h),
  };
}

/** Decode and cache an offscreen HTMLCanvasElement for a packed pixtuoid sprite frame. */
export function getPixtuoidSpriteCanvas(
  key: PixtuoidSpriteKey,
  frameIndex = 0,
): HTMLCanvasElement {
  const spec = PIXTUOID_SPRITES[key];
  const normalizedIdx = ((frameIndex % spec.frames.length) + spec.frames.length) % spec.frames.length;
  const cacheKey = `${key}:${normalizedIdx}`;
  const hit = DECODED_FRAME_CACHE.get(cacheKey);
  if (hit) return hit;

  const canvas = document.createElement("canvas");
  canvas.width = spec.w;
  canvas.height = spec.h;
  const ctx = canvas.getContext("2d");
  if (ctx) {
    const indices = decodeRleIndices(spec.frames[normalizedIdx], spec.w * spec.h);
    const img = ctx.createImageData(spec.w, spec.h);
    const data = img.data;
    for (let i = 0; i < indices.length; i++) {
      const idx = indices[i];
      if (idx === 0) continue;
      const hex = PIXTUOID_PALETTE[idx - 1];
      if (!hex) continue;
      const off = i * 4;
      data[off] = Number.parseInt(hex.slice(1, 3), 16);
      data[off + 1] = Number.parseInt(hex.slice(3, 5), 16);
      data[off + 2] = Number.parseInt(hex.slice(5, 7), 16);
      data[off + 3] = 255;
    }
    ctx.putImageData(img, 0, 0);
  }
  DECODED_FRAME_CACHE.set(cacheKey, canvas);
  return canvas;
}
